/* u009 · BED4BOOK marka, menü ve Liquid Glass arayüz
   - Platform logosu: orijinal BED4BOOK logosu (yüklenmiş özel logo yine önceliklidir).
   - Menü: gerçek sistemin (agent.bed4book.com) ana menü başlıkları ve sırası; ekranlar silinmez, yetkiler değişmez.
   - Arayüz: gerçek sistemdeki tema değişkenleri ve Liquid Glass yüzeyler (gündüz / gece / sistemle aynı). */
const UI = B4M.ui, BRU = B4M.uiBrand, NV = B4M.vNav, db = () => B4M.db;
const LOGO = "data:image/png;base64,";
BRU.platformLogo = LOGO;
const basePLogo = BRU.pLogo;
BRU.pLogo = () => (basePLogo && basePLogo()) || LOGO;
BRU.amblem = (sz = 52) => `<img class="plogo" src="${LOGO}" alt="BED4BOOK" style="height:${sz}px;width:auto;display:block">`;
BRU.word = () => "";
const baseLogo = BRU.logo;
BRU.logo = (x, sz = 52) => x ? baseLogo(x, sz) : `<img class="plogo" src="${U.esc(BRU.pLogo())}" alt="BED4BOOK" style="height:${Math.max(sz, 44)}px;max-width:300px;object-fit:contain;display:block">`;
/* Back Office menüsü: gerçek sistemin başlıkları (Panel · Rezervasyonlar · Oteller · Pazarlar · Acenteler ve kullanıcılar · Para birimleri ve kurlar …) */
if (NV && NV.H) NV.H.splice(0, NV.H.length,
  ["Panel", [["Panel", [["o"]]]]],
  ["Rezervasyonlar", [["Rezervasyonlar", [["res"]]]]],
  ["Oteller", [["Envanter", [["e"]]], ["Otel kontratları", [["hk"]]], ["Fiyat analizi", [["fa"]]]]],
  ["Pazarlar", [["Platform markup", [["pr"]]], ["Kurallar", [["r"]]], ["Parametreler", [["acc", { acT: "fprm" }]]],
    ["Commercial", [["cm", { cmT: "cs" }, "Satış"], ["cm", { cmT: "mkt" }, "Pazarlama"], ["cm", { cmT: "kt" }, "Sözleşme takibi"], ["cm", { cmT: "legal" }, "Legal"]]]]],
  ["Acenteler ve kullanıcılar", [["DMC'ler ve lisanslar", [["lic", null, "Müşteriler ve lisanslar"], ["s", null, "DMC'ler"]]], ["Satış hesapları", [["a"]]], ["Sözleşmeler", [["k"]]], ["Kullanıcılar", [["us"]]]]],
  ["Para birimleri ve kurlar", [["Kurlar", [["acc", { acT: "fx" }, "Kurlar"]]]]],
  ["Transfer / Tur / Uçak", [["Rehber satışları", [["gs"]]]]],
  ["Muhasebe", [["Genel", [["acc", { acT: "o" }]]], ["Ödemeler", [["acc", { acT: "pay" }, "Ödeme onayları"], ["acc", { acT: "dp" }, "DMC ödemeleri"], ["acc", { acT: "cm" }, "Komisyonlar"]]],
    ["Banka ve cari", [["acc", { acT: "bk" }, "Banka ve ekstre"], ["acc", { acT: "l" }, "Cari hareketler"]]],
    ["Gider ve personel", [["acc", { acT: "fx2" }, "Giderler"], ["acc", { acT: "fsal" }, "Maaşlar ve talepler"], ["acc", { acT: "fbon" }, "Prim"]]]]],
  ["Raporlar", [["Finans raporu", [["acc", { acT: "fr" }]]], ["Bütçe", [["acc", { acT: "fbud" }]]], ["Tanıtım gelirleri", [["acc", { acT: "fpro" }]]]]],
  ["Rebooking", [["Rebooking", [["rbo"]]]]],
  ["Entegrasyonlar / H2H", [["Entegrasyon merkezi", [["int"]]], ["Agent merkezi", [["ag"]]]]],
  ["Platform markası", [["Platform markası", [["br"]]], ["İşlem kaydı", [["log"]]]]]);
/* Liquid Glass — gerçek sistemin renk ve cam değişkenleriyle */
if (typeof document != "undefined") { const st = document.createElement("style"); st.id = "b4b-glass"; st.textContent = `
:root{--ac:#bc0019;--gd:#e30613;--on:#fff;--bg:#f4f5f7;--sf:rgba(255,255,255,.72);--tx:#20242d;--mu:#525b69;--ln:rgba(40,46,59,.14);--glass:rgba(255,255,255,.62);--glass-b:rgba(255,255,255,.55);--glass-sh:0 12px 34px rgba(28,33,46,.10)}
:root[data-theme="dark"]{--ac:#ff5966;--gd:#e30613;--on:#fff;--bg:#0b0d12;--sf:rgba(28,31,40,.72);--tx:#f6f6f8;--mu:#adb0ba;--ln:rgba(255,255,255,.14);--glass:rgba(28,31,40,.62);--glass-b:rgba(255,255,255,.14);--glass-sh:0 12px 34px rgba(0,0,0,.35)}
@media(prefers-color-scheme:dark){:root:not([data-theme="light"]){--ac:#ff5966;--gd:#e30613;--on:#fff;--bg:#0b0d12;--sf:rgba(28,31,40,.72);--tx:#f6f6f8;--mu:#adb0ba;--ln:rgba(255,255,255,.14);--glass:rgba(28,31,40,.62);--glass-b:rgba(255,255,255,.14);--glass-sh:0 12px 34px rgba(0,0,0,.35)}}
body{background:radial-gradient(ellipse at 100% 0,rgba(227,6,19,.22) 0,transparent 42%),radial-gradient(ellipse at 0 100%,rgba(227,6,19,.10) 0,transparent 40%),var(--bg);background-attachment:fixed}
.lgo{background:var(--glass);border:1px solid var(--glass-b);box-shadow:var(--glass-sh);border-radius:18px;padding:10px 16px;backdrop-filter:blur(18px) saturate(1.4);-webkit-backdrop-filter:blur(18px) saturate(1.4)}
.lgo .plogo,.plogo{height:56px!important;width:auto;border-radius:10px}
.box,.card,.panel,section.bx,.bx{background:var(--glass);border:1px solid var(--glass-b);box-shadow:var(--glass-sh);border-radius:18px;backdrop-filter:blur(18px) saturate(1.4);-webkit-backdrop-filter:blur(18px) saturate(1.4)}
.sidenav{background:var(--glass);border:1px solid var(--glass-b);border-radius:18px;padding:10px;backdrop-filter:blur(18px) saturate(1.4);-webkit-backdrop-filter:blur(18px) saturate(1.4);box-shadow:var(--glass-sh)}
.sidenav button.on,.tabs button.on{background:linear-gradient(115deg,#f30d24,#b10018);color:#fff;border-color:transparent;border-radius:12px}
.sidenav .gh.cur{color:var(--ac)}
button.g,.g{background:var(--glass);border:1px solid var(--glass-b);border-radius:12px;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px)}
button.p,.p{background:linear-gradient(115deg,#f30d24,#b10018);color:#fff;border:0;border-radius:12px}
input,select,textarea{background:var(--sf);border-radius:12px;border:1px solid var(--ln)}
@supports not (backdrop-filter:blur(1px)){.lgo,.box,.card,.panel,.bx,.sidenav,button.g{background:var(--sf)}}`;
  (document.head || document.documentElement).appendChild(st); }
